<script setup>
import { Head, router } from '@inertiajs/vue3'; import { ref } from 'vue'; import AppLayout from '../Layouts/AppLayout.vue';
defineProps({records:Object,pendingInvoices:Array,totals:Object}); const form=ref({}); function save(){router.post('/flujo-caja',form.value)} function remove(id){router.delete(`/flujo-caja/${id}`)}
</script>
<template><Head title="Flujo de Caja"/><AppLayout><main class="module-page"><h2>Flujo de Caja B2G</h2><div class="module-toolbar"><b>Ingresos manuales: L {{totals.manual}}</b><b>Cobrado: L {{totals.received}}</b><b>Por cobrar: L {{totals.pending}}</b></div><form class="module-form" @submit.prevent="save"><input v-model="form.concept" required placeholder="Concepto"><input v-model="form.amount" required type="number" min="0.01" placeholder="Monto"><input v-model="form.received_at" required type="date"><textarea v-model="form.notes" placeholder="Notas"/><button class="module-primary">Registrar ingreso</button></form><h3>Ingresos manuales</h3><p v-for="row in records.data" :key="row.id">{{row.received_at}} · {{row.concept}} · L {{row.amount}} <button class="row-action delete" @click="remove(row.id)">Eliminar</button></p><h3>Proyección por cobrar</h3><p v-for="invoice in pendingInvoices" :key="invoice.id">{{invoice.number}} · L {{invoice.amount}} · {{invoice.due_at}}</p></main></AppLayout></template>
